// Package tuning holds the MariaDB server variables admins may change in the
// panel. Values are validated against fixed ranges by the panel and again by
// the worker, which writes them to an include file only MariaDB's OS user can
// write and sets them with SET GLOBAL. Everything else in the server
// configuration stays generated by start.sh.
package tuning

import (
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type Kind int

const (
	Integer  Kind = iota
	Memory        // base unit kB
	Duration      // base unit s
)

type Param struct {
	Name    string
	Kind    Kind
	Restart bool // needs a server restart, otherwise SET GLOBAL applies it
	Help    string
	Also    []string // set to the same value, e.g. max_heap_table_size with tmp_table_size
	min     func(memMB int64) int64
	max     func(memMB int64) int64
	def     func(memMB int64) string
	defNote string // explains a computed or special default, shown after it
}

func fixed(n int64) func(int64) int64 { return func(int64) int64 { return n } }
func ofMemory(div int64) func(int64) int64 {
	return func(memMB int64) int64 { return memMB * 1024 / div }
}
func text(s string) func(int64) string { return func(int64) string { return s } }

// Params are the editable variables, in display order. The defaults match start.sh.
var Params = []Param{
	{Name: "max_connections", Kind: Integer, min: fixed(20), max: fixed(2000), def: text("100"),
		Help: "Upper limit for all connections together. The connection limits of the logins should add up to less."},
	{Name: "innodb_buffer_pool_size", Kind: Memory, min: fixed(32 * 1024), max: func(m int64) int64 { return m * 1024 * 3 / 4 },
		def: func(m int64) string { return fmt.Sprintf("%dMB", m/4) }, defNote: "a quarter of the app memory",
		Help: "Cache for table and index data. Empty follows the memory limit of the app."},
	{Name: "tmp_table_size", Kind: Memory, Also: []string{"max_heap_table_size"}, min: fixed(1024), max: ofMemory(4), def: text("16MB"),
		Help: "Largest in-memory temporary table per query, larger ones go to disk. Sets max_heap_table_size to the same value."},
	{Name: "sort_buffer_size", Kind: Memory, min: fixed(32), max: ofMemory(16), def: text("2MB"),
		Help: "Memory per sort. Each connection that sorts allocates it."},
	{Name: "max_statement_time", Kind: Duration, min: fixed(0), max: fixed(24 * 3600), def: text("0"), defNote: "off",
		Help: "Cancels statements that run longer. Snapshots, restores and imports are not affected."},
	{Name: "idle_transaction_timeout", Kind: Duration, min: fixed(0), max: fixed(7 * 24 * 3600), def: text("0"), defNote: "off",
		Help: "Ends sessions that keep a transaction open without doing anything."},
	{Name: "wait_timeout", Kind: Duration, min: fixed(60), max: fixed(7 * 24 * 3600), def: text("8h"),
		Help: "Ends idle sessions. Too short breaks connection pools that keep idle connections open."},
}

func Lookup(name string) (Param, bool) {
	for _, p := range Params {
		if p.Name == name {
			return p, true
		}
	}
	return Param{}, false
}

func Names() []string {
	out := make([]string, len(Params))
	for i, p := range Params {
		out[i] = p.Name
	}
	return out
}

// Default is the value used when the field is empty.
func (p Param) Default(memMB int64) string { return p.def(memMB) }

// DefaultHint is Default with its explanation, for the form hint.
func (p Param) DefaultHint(memMB int64) string {
	if p.defNote == "" {
		return p.def(memMB)
	}
	return p.def(memMB) + ", " + p.defNote
}

// Range describes the allowed values for the form hint.
func (p Param) Range(memMB int64) string {
	return format(p.Kind, p.min(memMB)) + " to " + format(p.Kind, p.max(memMB))
}

var (
	integerRe  = regexp.MustCompile(`^[0-9]{1,12}$`)
	memoryRe   = regexp.MustCompile(`^([0-9]{1,12}) ?(?i)(kb|mb|gb|tb)$`)
	durationRe = regexp.MustCompile(`^([0-9]{1,12}) ?(s|min|h|d)$`)
)

var (
	memoryUnits   = map[string]int64{"kB": 1, "MB": 1024, "GB": 1024 * 1024, "TB": 1024 * 1024 * 1024}
	memoryCanon   = map[string]string{"kb": "kB", "mb": "MB", "gb": "GB", "tb": "TB"}
	durationUnits = map[string]int64{"s": 1, "min": 60, "h": 3600, "d": 24 * 3600}
)

// Normalize checks a value and returns it in the form stored by the panel,
// digits and a unit.
func (p Param) Normalize(value string, memMB int64) (string, error) {
	_, out, err := p.parse(value, memMB)
	return out, err
}

func (p Param) parse(value string, memMB int64) (int64, string, error) {
	value = strings.TrimSpace(value)
	var n, base int64
	var out string
	switch p.Kind {
	case Integer:
		if !integerRe.MatchString(value) {
			return 0, "", fmt.Errorf("%s must be a whole number", p.Name)
		}
		n, _ = strconv.ParseInt(value, 10, 64)
		base, out = n, strconv.FormatInt(n, 10)
	case Memory:
		m := memoryRe.FindStringSubmatch(value)
		if m == nil {
			return 0, "", fmt.Errorf("%s must be a size like 64MB or 1GB", p.Name)
		}
		n, _ = strconv.ParseInt(m[1], 10, 64)
		unit := memoryCanon[strings.ToLower(m[2])]
		base, out = n*memoryUnits[unit], strconv.FormatInt(n, 10)+unit
	case Duration:
		if value == "0" {
			base, out = 0, "0"
			break
		}
		m := durationRe.FindStringSubmatch(value)
		if m == nil {
			return 0, "", fmt.Errorf("%s must be 0 or a duration like 30s, 10min or 2h", p.Name)
		}
		n, _ = strconv.ParseInt(m[1], 10, 64)
		base, out = n*durationUnits[m[2]], strconv.FormatInt(n, 10)+m[2]
	}
	if lo, hi := p.min(memMB), p.max(memMB); base < lo || base > hi {
		return 0, "", fmt.Errorf("%s must be between %s and %s", p.Name, format(p.Kind, lo), format(p.Kind, hi))
	}
	return base, out, nil
}

// serverValue is the value in MariaDB's own unit: bytes or seconds.
func (p Param) serverValue(value string, memMB int64) (string, error) {
	base, _, err := p.parse(value, memMB)
	if err != nil {
		return "", err
	}
	if p.Kind == Memory {
		base *= 1024
	}
	return strconv.FormatInt(base, 10), nil
}

func format(k Kind, n int64) string {
	switch k {
	case Memory:
		switch {
		case n%(1024*1024) == 0 && n >= 1024*1024:
			return strconv.FormatInt(n/(1024*1024), 10) + "GB"
		case n%1024 == 0 && n >= 1024:
			return strconv.FormatInt(n/1024, 10) + "MB"
		}
		return strconv.FormatInt(n, 10) + "kB"
	case Duration:
		switch {
		case n == 0:
			return "0"
		case n%(24*3600) == 0:
			return strconv.FormatInt(n/(24*3600), 10) + "d"
		case n%3600 == 0:
			return strconv.FormatInt(n/3600, 10) + "h"
		case n%60 == 0:
			return strconv.FormatInt(n/60, 10) + "min"
		}
		return strconv.FormatInt(n, 10) + "s"
	}
	return strconv.FormatInt(n, 10)
}

// FormatServer turns a value read from MariaDB (bytes or seconds) into the
// panel's notation, for the running value.
func (p Param) FormatServer(v string) string {
	f, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return v
	}
	n := int64(f)
	if p.Kind == Memory {
		if n%1024 != 0 {
			return strconv.FormatInt(n, 10) + " bytes"
		}
		n /= 1024
	}
	if float64(n) != f && p.Kind != Memory {
		return v
	}
	return format(p.Kind, n)
}

// Validate normalizes the non-empty values. Unknown names are an error, so a
// changed panel cannot smuggle other variables past the worker.
func Validate(values map[string]string, memMB int64) (map[string]string, []error) {
	out := map[string]string{}
	var errs []error
	for name, v := range values {
		p, ok := Lookup(name)
		if !ok {
			errs = append(errs, fmt.Errorf("%s cannot be changed in the panel", name))
			continue
		}
		if strings.TrimSpace(v) == "" {
			continue
		}
		n, err := p.Normalize(v, memMB)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		out[name] = n
	}
	return out, errs
}

func Encode(values map[string]string) string {
	if len(values) == 0 {
		return ""
	}
	b, _ := json.Marshal(values)
	return string(b)
}

func Decode(s string) (map[string]string, error) {
	out := map[string]string{}
	if s == "" {
		return out, nil
	}
	err := json.Unmarshal([]byte(s), &out)
	return out, err
}

// Assignment is one variable in MariaDB's unit, Value is digits only.
type Assignment struct{ Name, Value string }

// Assignments returns what to set for validated values, including the
// variables that follow another one. Variables without a value get the
// default from start.sh, so removing a value in the panel resets it.
func Assignments(values map[string]string, memMB int64) ([]Assignment, error) {
	var out []Assignment
	for _, p := range Params {
		v, ok := values[p.Name]
		if !ok {
			v = defaultValue(p.Name, memMB)
		}
		sv, err := p.serverValue(v, memMB)
		if err != nil {
			return nil, err
		}
		for _, name := range append([]string{p.Name}, p.Also...) {
			out = append(out, Assignment{name, sv})
		}
	}
	return out, nil
}

// defaultValue mirrors start.sh, in the panel's notation.
func defaultValue(name string, memMB int64) string {
	switch name {
	case "max_connections":
		return "100"
	case "innodb_buffer_pool_size":
		return strconv.FormatInt(max(memMB/4, 32), 10) + "MB"
	case "tmp_table_size":
		return "16MB"
	case "sort_buffer_size":
		return "2MB"
	case "wait_timeout":
		return "8h"
	}
	return "0"
}

// Render returns the include file for the server configuration with the
// values the admin set.
func Render(values map[string]string, memMB int64) (string, error) {
	var b strings.Builder
	b.WriteString("# Written by the panel worker from the admin settings. Changes here are overwritten.\n[mariadbd]\n")
	for _, p := range Params {
		v, ok := values[p.Name]
		if !ok {
			continue
		}
		sv, err := p.serverValue(v, memMB)
		if err != nil {
			return "", err
		}
		for _, name := range append([]string{p.Name}, p.Also...) {
			fmt.Fprintf(&b, "%s = %s\n", name, sv)
		}
	}
	return b.String(), nil
}

// MemoryMB reads the container memory limit like start.sh does.
func MemoryMB() int64 {
	limit := int64(2 * 1024 * 1024 * 1024)
	if b, err := os.ReadFile("/sys/fs/cgroup/memory.max"); err == nil {
		if v, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64); err == nil {
			limit = v
		}
	} else if b, err := os.ReadFile("/sys/fs/cgroup/memory/memory.limit_in_bytes"); err == nil {
		if v, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64); err == nil {
			limit = v
		}
	}
	return limit / 1024 / 1024
}
